def compute(vars):
    q3_revenue = vars["v1"]
    q4_revenue = vars["v2"]
    change = q4_revenue - q3_revenue

    return {
        "value": change,
        "trace": {
            "q3_revenue": q3_revenue,
            "q4_revenue": q4_revenue,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
